    document.addEventListener("change",event=>{if(!state.work?.schedule)return;const scheduleItem=state.work.schedule.items.find(row=>row.id===$("#schedule-drawer")?.dataset.itemId);if(event.target.closest("#schedule-drawer")&&scheduleItem&&event.target.dataset.scheduleField){const field=event.target.dataset.scheduleField;if(field==="done"){scheduleItem.status=event.target.checked?"Concluída":"Planejada";scheduleItem.progress=event.target.checked?100:0;$("#schedule-drawer [data-schedule-field=status]").value=scheduleItem.status}else{scheduleItem[field]=["budget","progress"].includes(field)?Number(event.target.value)||0:event.target.value;if(field==="status"){const done=scheduleItem.status==="Concluída";if(done)scheduleItem.progress=100;else if(Number(scheduleItem.progress)===100)scheduleItem.progress=0;$("#schedule-drawer [data-schedule-field=done]").checked=done}}renderSchedule();enhanceScheduleVisuals();scheduleSave();return}const quoteRow=event.target.closest("[data-schedule-quote]");if(quoteRow&&scheduleItem){const quote=scheduleItem.quotes[Number(quoteRow.dataset.scheduleQuote)];if(quote){quote[event.target.dataset.quoteField]=event.target.dataset.quoteField==="value"?Number(event.target.value)||0:event.target.value;openScheduleDrawer(scheduleItem.id);scheduleSave();return}}const supplierRow=event.target.closest("[data-schedule-supplier]");if(supplierRow){const supplier=state.work.schedule.suppliers.find(row=>row.id===supplierRow.dataset.scheduleSupplier),inputs=supplierRow.querySelectorAll("input");const fields=["quote","phone","email","notes"];fields.forEach((field,index)=>{if(inputs[index])supplier[field]=field==="quote"?Number(inputs[index].value)||0:inputs[index].value});scheduleSave()}});
