    $("#work-add-phase").addEventListener("click",()=>{state.work.phases.push({id:uid("etapa"),name:"Nova etapa",weight:5,progress:0,status:"Não iniciada",owner:"",plannedStart:"",plannedEnd:"",actualStart:"",actualEnd:"",notes:"",applicable:true,order:state.work.phases.length});renderPhases();renderExecutive();scheduleSave()});
    $("#work-add-document").addEventListener("click",()=>{state.work.documents.push({id:uid("doc"),title:"Novo documento",required:true,status:"Pendente",expiry:"",owner:"",notes:"",driveUrl:"",files:[]});renderDocuments();renderExecutive();scheduleSave()});
