  async function init(options={}){if(state.initialized)return;state.initialized=true;state.client=options.client||state.client;state.toast=options.toast||state.toast;state.orders=options.orders||(()=>[]);bind()}
  async function enter(){if(!state.work||state.work.clientId!==state.client.id)await load();else render()}
  async function setClient(client){clearTimeout(state.saveTimer);state.client=client||state.client;state.work=null;state.budgetCategory="Todas";state.budgetSubcategory="Todas";state.scheduleSupplierDraft={category:"",name:""};if(!$("#work").hidden)await load()}
  function syncWork(work){if(work?.clientId!==state.client.id)return;state.work=work;render();setSaveStatus("Salvo localmente")}
  async function openBudgetItem(itemId){if(!state.work||state.work.clientId!==state.client.id)await load();const item=state.work?.budget?.items?.find(row=>row.id===itemId);if(!item)return false;state.budgetCategory=item.category;state.budgetSubcategory=item.subcategory;renderBudget();renderBudgetOverview();showTab("budget");setTimeout(()=>{$(`[data-budget-row-id="${CSS.escape(itemId)}"]`)?.scrollIntoView({behavior:"smooth",block:"center"})},120);return true}
  window.WorkManagement={init,enter,setClient,syncWork,syncDocuments,openBudgetItem,request,hasWork:()=>!!state.work};
